<script setup lang="ts">
import { ref, onMounted, onBeforeUnmount, watch } from 'vue'; import FloatButton from './FloatButton.vue';
const props = withDefaults(defineProps<{ visibilityHeight?: number; target?: () => HTMLElement | Window; duration?: number; tooltip?: string }>(), { visibilityHeight: 400, duration: 450, tooltip: '回到顶部' }); const emit = defineEmits<{ click: [] }>(); const visible = ref(false); let cleanup: (() => void) | undefined; let frame = 0;
function start() { cleanup?.(); const container = props.target?.() ?? window; const check = () => { visible.value = (container === window ? window.scrollY : (container as HTMLElement).scrollTop) > props.visibilityHeight; }; check(); container.addEventListener('scroll', check, { passive: true }); cleanup = () => container.removeEventListener('scroll', check); }
onMounted(() => { start(); watch(() => [props.target, props.visibilityHeight], start); }); onBeforeUnmount(() => { cleanup?.(); cancelAnimationFrame(frame); });
function scroll() { const container = props.target?.() ?? window; cancelAnimationFrame(frame); if (matchMedia('(prefers-reduced-motion: reduce)').matches || props.duration <= 0) container.scrollTo({ top: 0 }); else { const start = container === window ? scrollY : (container as HTMLElement).scrollTop; const begin = performance.now(); const tick = (now: number) => { const progress = Math.min(1, (now - begin) / props.duration); container.scrollTo({ top: start * (1 - progress) ** 3 }); if (progress < 1) frame = requestAnimationFrame(tick); }; frame = requestAnimationFrame(tick); } emit('click'); }
</script>
